148	  /// The basename of `argv[0]` as the process was originally exec'd (e.g. `claude`, `vim`), or nil
149	  /// if it can't be resolved. Deliberately NOT `proc_name`/`p_comm`: some CLIs (Claude Code among
150	  /// them, observed in the wild) rename their own process title after launch — `p_comm` then reads
151	  /// as their version string ("2.1.232"), not the command a user typed. `KERN_PROCARGS2` returns
152	  /// the ORIGINAL exec-time argv snapshot, unaffected by any later self-renaming, and matches what
153	  /// the shell's own preexec title-report already uses for a live (non-reattached) pane.
154	  static func executableName(processID: pid_t) -> String? {
155	    guard processID > 0 else { return nil }
156	    var mib: [Int32] = [CTL_KERN, KERN_PROCARGS2, processID]
157	    var size = 0
158	    guard sysctl(&mib, 3, nil, &size, nil, 0) == 0, size > 4 else { return nil }
159	    var buffer = [UInt8](repeating: 0, count: size)
160	    guard sysctl(&mib, 3, &buffer, &size, nil, 0) == 0, size > 4 else { return nil }
161	
162	    let argc = buffer.withUnsafeBytes { $0.loadUnaligned(as: Int32.self) }
163	    guard argc > 0 else { return nil }
164	
165	    // Layout: argc, then the exec path (NUL-terminated), then NUL padding, then argv[0..argc-1]
166	    // each NUL-terminated. Skip the exec path and padding to reach argv[0].
167	    var offset = 4
168	    while offset < size, buffer[offset] != 0 { offset += 1 }
169	    while offset < size, buffer[offset] == 0 { offset += 1 }
170	    guard offset < size else { return nil }
171	
172	    let start = offset
173	    while offset < size, buffer[offset] != 0 { offset += 1 }
174	    guard offset > start else { return nil }
175	    let argv0 = String(decoding: buffer[start..<offset], as: UTF8.self)
176	    guard let lastSlash = argv0.lastIndex(of: "/") else { return argv0 }
177	    // A trailing slash (argv0 == "foo/") makes this slice empty — nil, not "", so a caller's
178	    // `if let name` doesn't pass through and synthesize a blank title.
179	    let basename = argv0[argv0.index(after: lastSlash)...]
180	    return basename.isEmpty ? nil : String(basename)
181	  }
