4	/// One curated entry (issue #141): identifies a CLI/TUI by its exec'd basename (or, for tools that
5	/// rewrite their own title, a literal provider title) and names the bundled `ToolLogo-<id>` imageset
6	/// carrying its real brand favicon. Loaded from `Resources/tool-logos/registry.json` — the SAME file
7	/// `Scripts/fetch-tool-logos.sh` reads to know what to fetch, so the fetch list and the match list
8	/// can't drift apart.
9	struct ToolLogoEntry: Codable, Equatable {
10	  let id: String
11	  let displayName: String
12	  let executables: [String]
13	  let titles: [String]?
14	  let faviconSource: String
15	}
16	
17	/// Latched onto a running terminal tab (mirrors `AgentBackend`, but data-driven and not limited to
18	/// two cases). Deliberately smaller than `ToolLogoEntry` — a tab only needs to remember the match.
19	struct RecognizedTool: Equatable {
20	  let id: String
21	  let displayName: String
22	}
23	
24	enum ToolLogoRegistry {
25	  private static let logger = Logger(
26	    subsystem: "com.developwithstyle.workroom", category: "ToolLogoRegistry")
27	
28	  static let entries: [ToolLogoEntry] = loadEntries()
29	
30	  private static let byExecutable: [String: ToolLogoEntry] = {
31	    var map: [String: ToolLogoEntry] = [:]
32	    for entry in entries {
33	      for exe in entry.executables { map[exe] = entry }
34	    }
35	    return map
36	  }()
37	
38	  private static let byTitle: [String: ToolLogoEntry] = {
39	    var map: [String: ToolLogoEntry] = [:]
40	    for entry in entries {
41	      for title in entry.titles ?? [] { map[title.lowercased()] = entry }
42	    }
43	    return map
44	  }()
45	
46	  /// Pure data match — works even before `fetch-tool-logos.sh` has produced an imageset for the id,
47	  /// so it's directly unit-testable against `registry.json` content alone.
48	  ///
49	  /// Case-sensitive on purpose, mirroring `AgentTitleRecognition.backend(for:)`
50	  /// (`AgentUsage.swift`): a command title is the real, lower-case executable name, so comparing
51	  /// case-sensitively rejects prose like "Go to definition" matching the `go` entry.
52	  static func matchingEntry(forTitle title: String?) -> ToolLogoEntry? {
53	    guard let title else { return nil }
54	    let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
55	    guard !trimmed.isEmpty else { return nil }
56	    if let literal = byTitle[trimmed.lowercased()] { return literal }
57	    guard let first = trimmed.split(whereSeparator: \.isWhitespace).first else { return nil }
58	    let token = String(first).trimmingCharacters(in: CharacterSet(charactersIn: "\"'"))
59	    return byExecutable[(token as NSString).lastPathComponent]
60	  }
61	
62	  static func matchingEntry(forExecutableName name: String?) -> ToolLogoEntry? {
63	    guard let name else { return nil }
64	    return byExecutable[(name as NSString).lastPathComponent]
65	  }
66	
67	  /// The gate production call sites actually use: nil unless the id's real logo made it into
68	  /// Assets.xcassets. A `registry.json` entry can exist before the fetch script has been run for it
69	  /// (or a fetch failed for one tool) — this must never surface a broken/blank image.
70	  static func tool(forTitle title: String?) -> RecognizedTool? {
71	    matchingEntry(forTitle: title).flatMap(recognizedIfBundled)
72	  }
73	
74	  static func tool(forExecutableName name: String?) -> RecognizedTool? {
75	    matchingEntry(forExecutableName: name).flatMap(recognizedIfBundled)
76	  }
77	
78	  static func assetName(for id: String) -> String { "ToolLogo-\(id)" }
79	
80	  private static func recognizedIfBundled(_ entry: ToolLogoEntry) -> RecognizedTool? {
81	    guard NSImage(named: assetName(for: entry.id)) != nil else { return nil }
82	    return RecognizedTool(id: entry.id, displayName: entry.displayName)
83	  }
84	
85	  private static func loadEntries() -> [ToolLogoEntry] {
86	    guard
87	      let url = Bundle.main.url(
88	        forResource: "registry", withExtension: "json", subdirectory: "tool-logos")
89	    else {
90	      logger.error("tool-logos/registry.json not found in the app bundle")
91	      return []
92	    }
93	    do {
94	      let data = try Data(contentsOf: url)
95	      return try JSONDecoder().decode([ToolLogoEntry].self, from: data)
96	    } catch {
97	      logger.error("tool-logos/registry.json failed to decode: \(error, privacy: .public)")
98	      return []
99	    }
100	  }
101	}
