/// Lowercased before lookup (review finding) — matching `AgentProcessRecognition.backend(forProcessName:)`'s
/// precedent. Unlike the title-matching path above, a `proc_name`-resolved executable name is never
/// prose, so there's no "Go to definition" style false-positive risk to guard against by staying
/// case-sensitive here — and macOS's default case-insensitive filesystem means a real binary can
/// genuinely be invoked with non-lowercase casing. `byExecutable`'s own keys are already all-lowercase
/// as authored in `registry.json` (only the lookup side needed normalizing, not the map).
static func matchingEntry(forExecutableName name: String?) -> ToolLogoEntry? {
  guard let name else { return nil }
  return byExecutable[(name as NSString).lastPathComponent.lowercased()]
}

/// Case-INsensitive on purpose (review finding): a `proc_name`-resolved executable name is never
/// prose, so there's no false-positive risk to guard against here, unlike the title-matching path
/// below — and macOS's default case-insensitive filesystem means a real binary can genuinely be
/// invoked with non-lowercase casing (e.g. "Docker").
func testMatchesExecutableAliasesCaseInsensitively() {
  XCTAssertEqual(ToolLogoRegistry.matchingEntry(forExecutableName: "vim")?.id, "vim")
  XCTAssertEqual(ToolLogoRegistry.matchingEntry(forExecutableName: "vi")?.id, "vim")
  XCTAssertEqual(
    ToolLogoRegistry.matchingEntry(forExecutableName: "/opt/homebrew/bin/nvim")?.id, "nvim")
  XCTAssertEqual(ToolLogoRegistry.matchingEntry(forExecutableName: "Vim")?.id, "vim")
  XCTAssertEqual(ToolLogoRegistry.matchingEntry(forExecutableName: "DOCKER")?.id, "docker")
}
